 /// A UTC round-trip time as .NET ticks (100 ns since 0001-01-01 UTC); `None` when it does not parse.
 fn iso_ticks(iso: &str) -> Option<i64> {
     let t = iso.trim();
     if t.is_empty() {
         return None;
     }
     let d = DateTime::parse_from_rfc3339(t).ok()?.with_timezone(&Utc);
     Some(
