         let (name, bytes) = match e {
             Value::String(s) if !s.is_empty() => (s.clone(), -1),
             Value::Object(o) => {
                 let name = value_text(o.get("name"));
                 if name.is_empty() {
                     continue;
                 }
                 let bytes = match o.get("bytes") {
