 use std::path::{Path, PathBuf};
 use std::process::{Command, Output};
 use std::time::Duration;

 use c3::telemetry::notspooled::{self, LocalPaths};
 use serde_json::Value;

 fn c3_bin() -> PathBuf {
     PathBuf::from(env!("CARGO_BIN_EXE_c3"))
