 fn scratch(tag: &str) -> PathBuf {
     let nanos = std::time::SystemTime::now()
         .duration_since(std::time::UNIX_EPOCH)
         .map(|d| d.as_nanos())
         .unwrap_or(0);
     let p = std::env::temp_dir().join(format!("c3-ns-{tag}-{}-{nanos}", std::process::id()));
     std::fs::create_dir_all(&p).unwrap();
     p
