 /// One not-spooled line as the plugin writes it.
 fn line(time: &str, why: &str) -> String {
     format!("{{\"time\":\"{time}\",\"why\":\"{why}\"}}\n")
 }

 fn text(o: &Output) -> String {
     format!(
         "{}{}",
         String::from_utf8_lossy(&o.stdout),
         String::from_utf8_lossy(&o.stderr)
