+/// The recorded bytes of `name` in `folded_entries` output (`name=bytes`).
+fn len0_of(entries: &[String], name: &str) -> u64 {
+    entries
+        .iter()
+        .find_map(|e| e.strip_prefix(&format!("{name}=")))
+        .and_then(|b| b.parse().ok())
+        .unwrap()
+}
